// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleSuicide} from "../src/SimpleSuicide.sol";

contract InvMutTest is Test {
    SimpleSuicide c;
    function setUp() public { c = new SimpleSuicide(); }
    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(actor != address(0));
        vm.assume(amount > 0 && amount <= address(this).balance);
        vm.deal(actor, amount);

        bool notOwnerSuccess;
        vm.prank(actor);
        try c.sudicideAnyone() { notOwnerSuccess = true; } catch { notOwnerSuccess = false; }

        assertTrue(!notOwnerSuccess || actor == c.smartfix_owner());
    }
}
